import{_ as e,o as t,c as s,a3 as p}from"./chunks/framework.BMJIGmOB.js";const m=JSON.parse('{"title":"写好 Prompt 的四个层次","description":"从一句祈使句到可复用的工作流，Prompt 的差别往往不在辞藻，而在结构。","frontmatter":{"title":"写好 Prompt 的四个层次","description":"从一句祈使句到可复用的工作流，Prompt 的差别往往不在辞藻，而在结构。","date":"2026-09-23T00:00:00.000Z","category":"灵犀智算","subCategory":"大模型与 Agent","tags":["AI","Prompt","大模型"],"author":"闲生"},"headers":[],"relativePath":"posts/ai/llm/prompt-layers.md","filePath":"posts/ai/llm/prompt-layers.md"}'),n={name:"posts/ai/llm/prompt-layers.md"};function r(o,a,l,i,c,d){return t(),s("div",null,[...a[0]||(a[0]=[p(`<h1 id="写好-prompt-的四个层次" tabindex="-1">写好 Prompt 的四个层次 <a class="header-anchor" href="#写好-prompt-的四个层次" aria-label="Permalink to &quot;写好 Prompt 的四个层次&quot;">​</a></h1><p>同一件事，换一种问法，模型的输出可能天差地别。Prompt 的进步，通常发生在结构上。</p><h2 id="一、第一层-说清任务" tabindex="-1">一、第一层：说清任务 <a class="header-anchor" href="#一、第一层-说清任务" aria-label="Permalink to &quot;一、第一层：说清任务&quot;">​</a></h2><p>最基础的 Prompt 只回答三个问题：做什么、给谁做、输出成什么格式。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>你是资深后端工程师。</span></span>
<span class="line"><span>请把下面这段 Java 代码改写成使用 try-with-resources 的版本，</span></span>
<span class="line"><span>保留原有注释，并说明修改理由。</span></span></code></pre></div><h2 id="二、第二层-给上下文" tabindex="-1">二、第二层：给上下文 <a class="header-anchor" href="#二、第二层-给上下文" aria-label="Permalink to &quot;二、第二层：给上下文&quot;">​</a></h2><h3 id="角色、约束、示例" tabindex="-1">角色、约束、示例 <a class="header-anchor" href="#角色、约束、示例" aria-label="Permalink to &quot;角色、约束、示例&quot;">​</a></h3><ul><li>角色决定语气与知识边界；</li><li>约束排除不想要的答案；</li><li>示例比形容词更有效。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>输出要求：</span></span>
<span class="line"><span>1. 只输出修改后的代码；</span></span>
<span class="line"><span>2. 代码块语言标记为 java；</span></span>
<span class="line"><span>3. 不要解释。</span></span></code></pre></div><h2 id="三、第三层-拆步骤" tabindex="-1">三、第三层：拆步骤 <a class="header-anchor" href="#三、第三层-拆步骤" aria-label="Permalink to &quot;三、第三层：拆步骤&quot;">​</a></h2><p>复杂任务不要指望一次生成。先列提纲，再逐段展开，最后统一润色。每一步都可以单独校验。</p><h3 id="让模型自我检查" tabindex="-1">让模型自我检查 <a class="header-anchor" href="#让模型自我检查" aria-label="Permalink to &quot;让模型自我检查&quot;">​</a></h3><p>在最后加一句「先检查是否满足以上约束，再输出」，可以明显减少格式跑偏。</p><h2 id="四、第四层-变成工作流" tabindex="-1">四、第四层：变成工作流 <a class="header-anchor" href="#四、第四层-变成工作流" aria-label="Permalink to &quot;四、第四层：变成工作流&quot;">​</a></h2><p>当一段 Prompt 被反复使用，就该把它沉淀成模板：变量抽出来，步骤固定下来，接上脚本或 Agent。</p><p>Prompt 的上限，往往不是模型的能力，而是写 Prompt 的人对任务本身的理解。</p>`,16)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
